//! Link the `grit` binary's own hot code path (`hot-text.ld`) next to grit-lib's, and tell
//! integration tests whether hot-text layout is linked at all (LLD only).
//!
//! grit-lib's `hot-text-layout` feature places the library's hot functions in
//! `.text.grit_hot`. The CLI, clap and the library generics the CLI instantiates are left out
//! of that list, so `hot-text.ld` here (generated by `scripts/gen_hot_text_layout.py` from the
//! same profile) places them in `.text.grit_cli_hot` ahead of `.text`. It is passed to the
//! final link of the `grit` binary as an input file, which LLD reads as an implicit linker
//! script. The conditions match grit-lib's: x86_64 Linux GNU with LLD, and not
//! `GRIT_HOT_TEXT_LAYOUT=0`.

use std::path::PathBuf;

include!("../grit-lib/hot_text_linker_support.rs");

fn main() {
    println!("cargo:rustc-check-cfg=cfg(grit_hot_text_layout_disabled)");
    println!("cargo:rerun-if-changed=hot-text.ld");
    println!("cargo:rerun-if-changed=../grit-lib/hot_text_linker_support.rs");
    println!("cargo:rerun-if-env-changed=GRIT_HOT_TEXT_LAYOUT");
    println!("cargo:rerun-if-env-changed=RUSTFLAGS");
    println!("cargo:rerun-if-env-changed=CARGO_ENCODED_RUSTFLAGS");
    if std::env::var("GRIT_HOT_TEXT_LAYOUT").as_deref() == Ok("0")
        || std::env::var("TARGET").as_deref() != Ok("x86_64-unknown-linux-gnu")
        || !linker_supports_hot_text_layout()
    {
        println!("cargo:rustc-cfg=grit_hot_text_layout_disabled");
        return;
    }
    let Some(manifest_dir) = std::env::var_os("CARGO_MANIFEST_DIR") else {
        return;
    };
    let script = PathBuf::from(manifest_dir).join("hot-text.ld");
    if script.is_file() {
        println!("cargo:rustc-link-arg-bin=grit={}", script.display());
    }
}
